/*
 * punnet — route table.
 *
 * One source of truth for "which Facebook URLs are distractions". It is used by:
 *   - the declarativeNetRequest ruleset (generated by tools/build-rules.mjs) for full page loads,
 *   - the content script for Facebook's in-app (pushState) navigation and link clicks,
 *   - the tests.
 *
 * Blocklist, not allowlist: anything not listed here (Marketplace, Messenger, login,
 * checkpoints, settings, help, seller profiles) keeps working untouched.
 */
(function (root) {
  'use strict';

  // First path segment of Facebook areas that punnet sends back to Marketplace.
  const BLOCKED_SECTIONS = Object.freeze([
    'home.php', // the News Feed
    'watch',
    'reel',
    'reels',
    'stories',
    'groups',
    'gaming',
    'notifications',
    'friends',
    'feeds',
    'memories',
    'fundraisers',
    'events',
  ]);

  const HOSTS = Object.freeze(['facebook.com', 'www.facebook.com', 'web.facebook.com', 'm.facebook.com']);

  const escape = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  // RE2-compatible (declarativeNetRequest) and JS-compatible. Group 1 = optional subdomain.
  // Matches the bare home page ("/" with any query) or a blocked section followed by / ? # or end.
  const REDIRECT_REGEX =
    '^https://((?:www|web|m)\\.)?facebook\\.com/(?:(?:' +
    BLOCKED_SECTIONS.map(escape).join('|') +
    ')(?:[/?#].*)?|[?#].*)?$';

  const REDIRECT_SUBSTITUTION = 'https://\\1facebook.com/marketplace/';

  // Chrome compiles declarativeNetRequest regexes with RE2 under a small memory cap, and the
  // combined pattern above exceeds it. The ruleset therefore uses one small pattern per section
  // (plus the home page); tests check both shapes agree on every URL.
  const HOST_PREFIX = '^https://((?:www|web|m)\\.)?facebook\\.com/';
  const RULE_REGEXES = Object.freeze([
    HOST_PREFIX + '(?:[?#].*)?$',
    ...BLOCKED_SECTIONS.map((sec) => HOST_PREFIX + escape(sec) + '(?:[/?#].*)?$'),
  ]);

  const redirectRe = new RegExp(REDIRECT_REGEX);

  function toUrl(input) {
    try {
      return input instanceof URL ? input : new URL(String(input));
    } catch {
      return null;
    }
  }

  function isFacebookHost(host) {
    return HOSTS.includes(String(host).toLowerCase());
  }

  /** Where a URL should go instead, or null if it is fine as it is. */
  function redirectTarget(input) {
    const url = toUrl(input);
    if (!url || url.protocol !== 'https:' || !isFacebookHost(url.hostname)) return null;
    const m = redirectRe.exec(url.href);
    if (!m) return null;
    return 'https://' + (m[1] || '') + 'facebook.com/marketplace/';
  }

  /** What kind of Marketplace page this is (or 'other' / 'messages' / 'none'). */
  function pageKind(input) {
    const url = toUrl(input);
    if (!url || !isFacebookHost(url.hostname)) return 'none';
    const p = url.pathname.replace(/\/+$/, '') + '/';
    if (/^\/(messages|t)\//.test(p)) return 'messages';
    if (!p.startsWith('/marketplace/')) return 'other';
    if (/^\/marketplace\/item\/\d+\//.test(p)) return 'item';
    if (/^\/marketplace\/you\/saved\//.test(p)) return 'saved';
    if (/^\/marketplace\/inbox\//.test(p)) return 'inbox';
    if (/^\/marketplace\/(you|selling|create)\b/.test(p)) return 'account';
    if (/^\/marketplace\/(?:[^/]+\/)?search\//.test(p)) return 'search';
    if (/^\/marketplace\/category\//.test(p)) return 'category';
    if (/^\/marketplace\/profile\//.test(p)) return 'seller';
    return 'browse';
  }

  /** Listing id from an href like /marketplace/item/1234567890/?ref=... */
  function itemIdFromHref(href) {
    const m = /\/marketplace\/item\/(\d+)/.exec(String(href || ''));
    return m ? m[1] : null;
  }

  /** Marketplace search URL for a query, using Facebook's own query params. */
  function searchUrl(query, settings, origin) {
    const url = new URL('/marketplace/search/', origin || 'https://www.facebook.com');
    url.searchParams.set('query', String(query || '').trim());
    return withBuyerParams(url, settings) || url.href;
  }

  /**
   * Adds Facebook's own server-side params (newest first, price range) to a search page URL.
   * Only fills params that are absent, so a choice made in Facebook's own UI is never fought.
   * Returns the new href, or null if nothing needs to change.
   */
  function withBuyerParams(input, settings) {
    const url = toUrl(input);
    if (!url || pageKind(url) !== 'search' || !settings) return null;
    const q = url.searchParams;
    let changed = false;
    if (settings.newestFirst && !q.has('sortBy')) {
      q.set('sortBy', 'creation_time_descend');
      changed = true;
    }
    if (isPrice(settings.minPrice) && !q.has('minPrice')) {
      q.set('minPrice', String(Math.floor(settings.minPrice)));
      changed = true;
    }
    if (isPrice(settings.maxPrice) && !q.has('maxPrice')) {
      q.set('maxPrice', String(Math.ceil(settings.maxPrice)));
      changed = true;
    }
    return changed ? url.href : null;
  }

  function isPrice(v) {
    return typeof v === 'number' && Number.isFinite(v) && v >= 0;
  }

  const api = {
    BLOCKED_SECTIONS,
    HOSTS,
    REDIRECT_REGEX,
    REDIRECT_SUBSTITUTION,
    RULE_REGEXES,
    redirectTarget,
    pageKind,
    itemIdFromHref,
    searchUrl,
    withBuyerParams,
  };

  root.MarketMode = Object.assign(root.MarketMode || {}, { routes: api });
  if (typeof module === 'object' && module.exports) module.exports = api;
})(typeof globalThis !== 'undefined' ? globalThis : this);
